<?php
declare(strict_types=1);

function mg_investment_compliance_seed(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.compliance.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$actorId=(int)$actor['id'];
    $templates=[
      ['offering_exemption','exemption','Offering exemption confirmed','Counsel-supplied exemption and offering structure recorded.',1],
      ['counsel_round_review','counsel_review','Round documents reviewed by counsel','External counsel confirms the approved round package.',1],
      ['board_consent','board_approval','Board consent approved','Board or authorized corporate consent is recorded.',0],
      ['form_d','federal_filing','Form D filing tracked','Track deadline, filing reference, and receipt supplied by counsel.',1],
      ['state_notices','state_notice','State notice filings tracked','Track state notice requirements and receipts supplied by counsel.',1],
      ['investor_notices','investor_notice','Required investor notices delivered','Record required closing and post-closing notices.',1],
      ['tax_records','tax','Tax-document collection tracked','Record external W-9/W-8 and related tax-document status.',0],
      ['final_closing_package','other','Final closing package assembled','Counsel/accountant closing package and reconciliation references are complete.',1],
    ];
    $stmt=$pdo->prepare('INSERT INTO investment_compliance_requirements (public_id,round_id,requirement_key,category,title,description,status,counsel_required,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,? ,"not_started",?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title),description=VALUES(description),counsel_required=VALUES(counsel_required),updated_by_user_id=VALUES(updated_by_user_id),updated_at=NOW()');
    foreach($templates as $row)$stmt->execute([mg_investment_uuid(),(int)$round['id'],$row[0],$row[1],$row[2],$row[3],$row[4],$actorId,$actorId]);
    mg_audit('investment_compliance_seeded','investment_round',['round_id'=>$round['public_id'],'requirements'=>count($templates)],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_compliance_event(PDO $pdo,int $requirementId,?int $actorUserId,string $eventType,array $details=[]): void
{
    $allowed=['created','status_changed','assigned','deadline_changed','reference_added','completed','reopened','note'];if(!in_array($eventType,$allowed,true))throw new MgInvestmentException('Invalid compliance event type.');$pdo->prepare('INSERT INTO investment_compliance_events (public_id,requirement_id,actor_user_id,event_type,details_json,created_at) VALUES (?,?,?,?,?,NOW())')->execute([mg_investment_uuid(),$requirementId,$actorUserId,$eventType,$details?mg_investment_json_encode($details):null]);
}

function mg_investment_compliance_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.compliance.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$publicId=trim((string)($input['requirement_id']??''));$categories=['exemption','federal_filing','state_notice','board_approval','counsel_review','investor_notice','tax','other'];$statuses=['not_started','requested','in_progress','filed','confirmed','approved','changes_required','not_applicable','overdue'];$category=(string)($input['category']??'other');$status=(string)($input['status']??'not_started');if(!in_array($category,$categories,true)||!in_array($status,$statuses,true))throw new MgInvestmentException('Invalid compliance category or status.');$actorId=(int)$actor['id'];$url=mg_investment_url($input['external_url']??'');
    if($publicId===''){$publicId=mg_investment_uuid();$stmt=$pdo->prepare('INSERT INTO investment_compliance_requirements (public_id,round_id,requirement_key,category,title,description,status,counsel_required,due_at,completed_at,external_reference,external_url,assigned_user_id,notes,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,IF(? IN ("confirmed","approved","not_applicable"),NOW(),NULL),?,?,?,?,?,?,NOW(),NOW())');$stmt->execute([$publicId,(int)$round['id'],mg_investment_text($input['requirement_key']??'',120,2,'Requirement key'),$category,mg_investment_text($input['title']??'',220,2,'Requirement title'),mg_investment_long_text($input['description']??'',6000)?:null,$status,mg_investment_bool($input['counsel_required']??false)?1:0,mg_investment_date($input['due_at']??null),$status,mg_investment_text($input['external_reference']??'',220)?:null,$url,(int)($input['assigned_user_id']??0)?:null,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$actorId]);$id=(int)$pdo->lastInsertId();mg_investment_compliance_event($pdo,$id,$actorId,'created',['status'=>$status]);}
    else{$q=$pdo->prepare('SELECT * FROM investment_compliance_requirements WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($publicId,36,36,'Requirement identifier'),(int)$round['id']]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)throw new MgInvestmentException('Compliance requirement not found.',404);$stmt=$pdo->prepare('UPDATE investment_compliance_requirements SET category=?,title=?,description=?,status=?,counsel_required=?,due_at=?,completed_at=IF(? IN ("confirmed","approved","not_applicable"),COALESCE(completed_at,NOW()),NULL),external_reference=?,external_url=?,assigned_user_id=?,notes=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?');$stmt->execute([$category,mg_investment_text($input['title']??'',220,2,'Requirement title'),mg_investment_long_text($input['description']??'',6000)?:null,$status,mg_investment_bool($input['counsel_required']??false)?1:0,mg_investment_date($input['due_at']??null),$status,mg_investment_text($input['external_reference']??'',220)?:null,$url,(int)($input['assigned_user_id']??0)?:null,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,(int)$row['id']]);if((string)$row['status']!==$status)mg_investment_compliance_event($pdo,(int)$row['id'],$actorId,'status_changed',['from'=>$row['status'],'to'=>$status]);if((string)($row['external_reference']??'')!==mg_investment_text($input['external_reference']??'',220))mg_investment_compliance_event($pdo,(int)$row['id'],$actorId,'reference_added',['external_reference'=>mg_investment_text($input['external_reference']??'',220)]);}
    mg_audit('investment_compliance_saved','investment_compliance',['requirement_id'=>$publicId,'round_id'=>$round['public_id'],'status'=>$status],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_financial_request(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$record=mg_investment_closing_record($pdo,mg_investment_text($input['record_id']??'',36,36,'Closing record identifier'),true);$type=(string)($input['verification_type']??'funded_amount');$allowed=['signed_amount','funded_amount','funded_reversal','signed_reversal','adjustment'];if(!in_array($type,$allowed,true))throw new MgInvestmentException('Invalid financial verification type.');$amount=mg_investment_money($input['requested_amount']??0);$reason=mg_investment_long_text($input['request_reason']??'',4000,10,'Verification reason');$actorId=(int)$actor['id'];$previous=in_array($type,['signed_amount','signed_reversal'],true)?(int)$record['signed_amount_cents']:(int)$record['verified_funded_cents'];if(in_array($type,['funded_amount','funded_reversal'],true)&&$amount>(int)$record['signed_amount_cents'])throw new MgInvestmentException('Verified funded amount cannot exceed the verified signed amount.',409);if(in_array($type,['signed_amount','signed_reversal'],true)&&$amount<(int)$record['verified_funded_cents'])throw new MgInvestmentException('Signed amount cannot be lower than verified funded money.',409);$pending=$pdo->prepare('SELECT COUNT(*) FROM investment_financial_verification_requests WHERE closing_record_id=? AND verification_type=? AND status="pending"');$pending->execute([(int)$record['id'],$type]);if((int)$pending->fetchColumn()>0)throw new MgInvestmentException('A pending verification request already exists for this amount type.',409);$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_financial_verification_requests (public_id,round_id,closing_record_id,verification_type,requested_amount_cents,previous_amount_cents,status,evidence_reference,request_reason,submitted_by_user_id,submitted_at,created_at,updated_at) VALUES (?,?,?,?,?,? ,"pending",?,?,?,NOW(),NOW(),NOW())')->execute([$publicId,(int)$record['round_id'],(int)$record['id'],$type,$amount,$previous,mg_investment_text($input['evidence_reference']??'',220)?:null,$reason,$actorId]);if(in_array($type,['funded_amount','funded_reversal'],true)){$pdo->prepare('UPDATE investor_closing_records SET reported_funded_cents=?,funds_reported_at=NOW(),status=IF(? > 0,"funds_reported",status),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$amount,$amount,$actorId,(int)$record['id']]);mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'funding_reported',(string)$record['status'],$amount>0?'funds_reported':(string)$record['status'],$amount,['verification_request_id'=>$publicId,'evidence_reference'=>mg_investment_text($input['evidence_reference']??'',220)]);}else{mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'signature_reported',(string)$record['status'],(string)$record['status'],$amount,['verification_request_id'=>$publicId]);}mg_audit('investment_financial_verification_requested','investment_financial_verification',['request_id'=>$publicId,'record_id'=>$record['public_id'],'type'=>$type,'amount_cents'=>$amount],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$record['round_public_id']]);
}

function mg_investment_recalculate_round_totals(PDO $pdo,int $roundId,int $actorId): array
{
    $sum=$pdo->prepare('SELECT COALESCE(SUM(soft_commitment_cents),0),COALESCE(SUM(signed_cents),0),COALESCE(SUM(funded_cents),0) FROM investor_round_interests WHERE round_id=? AND status NOT IN ("passed","declined","archived")');$sum->execute([$roundId]);[$soft,$signed,$funded]=$sum->fetch(PDO::FETCH_NUM);$pdo->prepare('UPDATE investment_rounds SET soft_commitment_cents=?,signed_cents=?,funded_cents=?,status=CASE WHEN status IN ("cancelled","paused","closed") THEN status WHEN ?>=target_raise_cents AND target_raise_cents>0 THEN "minimum_reached" WHEN ?>0 AND status IN ("planning","awaiting_counsel","private_preview") THEN status ELSE status END,updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([(int)$soft,(int)$signed,(int)$funded,(int)$funded,(int)$funded,$actorId,$roundId]);return ['soft_commitment_cents'=>(int)$soft,'signed_cents'=>(int)$signed,'funded_cents'=>(int)$funded];
}

function mg_investment_financial_decide(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.verify');$requestPublicId=mg_investment_text($input['request_id']??'',36,36,'Verification request identifier');$decision=(string)($input['decision']??'approved');if(!in_array($decision,['approved','rejected'],true))throw new MgInvestmentException('Invalid verification decision.');$notes=mg_investment_long_text($input['decision_notes']??'',4000,10,'Decision notes');$actorId=(int)$actor['id'];$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT vr.*,cr.public_id AS record_public_id,cr.investor_user_id,cr.signed_amount_cents,cr.verified_funded_cents,cr.status AS record_status,r.public_id AS round_public_id FROM investment_financial_verification_requests vr INNER JOIN investor_closing_records cr ON cr.id=vr.closing_record_id INNER JOIN investment_rounds r ON r.id=vr.round_id WHERE vr.public_id=? LIMIT 1 FOR UPDATE');$q->execute([$requestPublicId]);$request=$q->fetch(PDO::FETCH_ASSOC);if(!$request)throw new MgInvestmentException('Financial verification request not found.',404);if($request['status']!=='pending')throw new MgInvestmentException('This financial verification request has already been resolved.',409);if((int)$request['submitted_by_user_id']===$actorId)throw new MgInvestmentException('The submitting administrator cannot approve or reject their own financial verification request.',409);$pdo->prepare('INSERT INTO investment_financial_verification_decisions (public_id,request_id,reviewer_user_id,decision,decision_notes,created_at) VALUES (?,?,?,?,?,NOW())')->execute([mg_investment_uuid(),(int)$request['id'],$actorId,$decision,$notes]);$pdo->prepare('UPDATE investment_financial_verification_requests SET status=?,resolved_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$decision,(int)$request['id']]);if($decision==='approved'){$type=(string)$request['verification_type'];$amount=(int)$request['requested_amount_cents'];$newStatus=(string)$request['record_status'];if(in_array($type,['signed_amount','signed_reversal'],true)){$newStatus=$amount>0?((int)$request['verified_funded_cents']>0?'funds_verified':'signed'):'soft_committed';$pdo->prepare('UPDATE investor_closing_records SET signed_amount_cents=?,status=?,investor_signed_at=IF(? > 0,COALESCE(investor_signed_at,NOW()),investor_signed_at),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$amount,$newStatus,$amount,$actorId,(int)$request['closing_record_id']]);$pdo->prepare('UPDATE investor_round_interests SET signed_cents=?,status=IF(? > 0,IF(funded_cents>0,"funded","signed"),IF(soft_commitment_cents>0,"soft_committed","interested")),updated_by_user_id=?,last_activity_at=NOW(),updated_at=NOW() WHERE round_id=? AND investor_user_id=?')->execute([$amount,$amount,$actorId,(int)$request['round_id'],(int)$request['investor_user_id']]);mg_investment_closing_event($pdo,(int)$request['closing_record_id'],$actorId,'adjustment',(string)$request['record_status'],$newStatus,$amount,['verification_type'=>$type,'request_id'=>$requestPublicId,'decision_notes'=>$notes]);}elseif(in_array($type,['funded_amount','funded_reversal'],true)){$newStatus=$amount>0?'funds_verified':((int)$request['signed_amount_cents']>0?'signed':'soft_committed');$pdo->prepare('UPDATE investor_closing_records SET verified_funded_cents=?,reported_funded_cents=?,status=?,funds_verified_at=IF(? > 0,NOW(),NULL),verified_by_user_id=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$amount,$amount,$newStatus,$amount,$actorId,$actorId,(int)$request['closing_record_id']]);$pdo->prepare('UPDATE investor_round_interests SET funded_cents=?,status=IF(? > 0,"funded",IF(signed_cents>0,"signed",IF(soft_commitment_cents>0,"soft_committed","interested"))),updated_by_user_id=?,last_activity_at=NOW(),updated_at=NOW() WHERE round_id=? AND investor_user_id=?')->execute([$amount,$amount,$actorId,(int)$request['round_id'],(int)$request['investor_user_id']]);mg_investment_closing_event($pdo,(int)$request['closing_record_id'],$actorId,'funding_verified',(string)$request['record_status'],$newStatus,$amount,['verification_type'=>$type,'request_id'=>$requestPublicId,'decision_notes'=>$notes]);}$totals=mg_investment_recalculate_round_totals($pdo,(int)$request['round_id'],$actorId);$pipelineStage=$newStatus==='funds_verified'?'funded':($newStatus==='signed'?'signed':null);if($pipelineStage)$pdo->prepare('UPDATE investor_pipeline_records SET stage=?,updated_by_user_id=?,updated_at=NOW() WHERE investor_user_id=?')->execute([$pipelineStage,$actorId,(int)$request['investor_user_id']]);mg_investment_pipeline_activity($pdo,(int)$request['investor_user_id'],(int)$request['round_id'],'commitment_update','Financial verification approved',$notes,$actorId,['request_id'=>$requestPublicId,'type'=>$type,'amount_cents'=>$amount,'round_totals'=>$totals]);}else{mg_investment_pipeline_activity($pdo,(int)$request['investor_user_id'],(int)$request['round_id'],'commitment_update','Financial verification rejected',$notes,$actorId,['request_id'=>$requestPublicId,'type'=>$request['verification_type']]);}$pdo->commit();mg_audit('investment_financial_verification_decided','investment_financial_verification',['request_id'=>$requestPublicId,'decision'=>$decision,'reviewer_user_id'=>$actorId],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$request['round_public_id']]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}

function mg_investment_reconciliation_create(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$type=(string)($input['snapshot_type']??'manual');if(!in_array($type,['manual','pre_close','rolling_close','final_close','post_close'],true))throw new MgInvestmentException('Invalid reconciliation snapshot type.');$q=$pdo->prepare('SELECT COALESCE(SUM(signed_amount_cents),0),COALESCE(SUM(verified_funded_cents),0),COUNT(*) FROM investor_closing_records WHERE round_id=? AND status NOT IN ("withdrawn","declined")');$q->execute([(int)$round['id']]);[$signed,$funded,$investors]=$q->fetch(PDO::FETCH_NUM);$capacityBase=(int)$round['maximum_raise_cents']>0?(int)$round['maximum_raise_cents']:(int)$round['target_raise_cents'];$available=max(0,$capacityBase-(int)$signed);$valuation=(int)$round['valuation_cap_cents'];$modeled=$valuation>0?(int)round(((int)$round['target_raise_cents']/($valuation+(int)$round['target_raise_cents']))*10000):0;$actual=$valuation>0?(int)round(((int)$funded/($valuation+(int)$funded))*10000):0;$inputs=['round'=>['public_id'=>$round['public_id'],'instrument_type'=>$round['instrument_type'],'target_raise_cents'=>(int)$round['target_raise_cents'],'maximum_raise_cents'=>(int)$round['maximum_raise_cents'],'valuation_cap_cents'=>$valuation,'discount_bps'=>(int)$round['discount_bps']],'investor_count'=>(int)$investors,'signed_cents'=>(int)$signed,'verified_funded_cents'=>(int)$funded];$output=['available_capacity_cents'=>$available,'target_vs_signed_cents'=>(int)$signed-(int)$round['target_raise_cents'],'target_vs_funded_cents'=>(int)$funded-(int)$round['target_raise_cents'],'modeled_dilution_bps'=>$modeled,'actual_estimated_dilution_bps'=>$actual,'dilution_variance_bps'=>$actual-$modeled,'disclaimer'=>'Administrative estimate only; not the official stock ledger or legal capitalization record.'];$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_cap_reconciliation_snapshots (public_id,round_id,snapshot_type,source_scenario_public_id,signed_cents,verified_funded_cents,target_raise_cents,available_capacity_cents,modeled_dilution_bps,actual_estimated_dilution_bps,inputs_json,output_json,created_by_user_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$publicId,(int)$round['id'],$type,mg_investment_text($input['source_scenario_public_id']??'',36)?:null,(int)$signed,(int)$funded,(int)$round['target_raise_cents'],$available,$modeled,$actual,mg_investment_json_encode($inputs),mg_investment_json_encode($output),(int)$actor['id']]);mg_audit('investment_cap_reconciliation_created','investment_round',['round_id'=>$round['public_id'],'snapshot_id'=>$publicId,'snapshot_type'=>$type],(int)$actor['id']);return ['snapshot'=>['public_id'=>$publicId,'inputs'=>$inputs,'output'=>$output],'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']])];
}

function mg_investment_closing_refresh_readiness(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$roundId=(int)$round['id'];$profileQ=$pdo->prepare('SELECT * FROM investment_closing_profiles WHERE round_id=? LIMIT 1');$profileQ->execute([$roundId]);$profile=$profileQ->fetch(PDO::FETCH_ASSOC);if(!$profile){mg_investment_closing_sync($pdo,(int)$actor['id']);$profileQ->execute([$roundId]);$profile=$profileQ->fetch(PDO::FETCH_ASSOC)?:[];}$blockers=[];$components=[];$components['governance']=(($profile['counsel_status']??'')==='approved'?10:0)+(($profile['board_status']??'')==='approved'?10:0);if($components['governance']<20)$blockers[]='Counsel and board approvals are incomplete.';$c=$pdo->prepare('SELECT COUNT(*) AS total,SUM(status IN ("confirmed","approved","not_applicable")) AS complete,SUM(status="overdue" OR (due_at<NOW() AND status NOT IN ("confirmed","approved","not_applicable"))) AS overdue FROM investment_compliance_requirements WHERE round_id=?');$c->execute([$roundId]);$compliance=$c->fetch(PDO::FETCH_ASSOC)?:[];$components['compliance']=(int)($compliance['total']??0)>0?(int)round(20*((int)($compliance['complete']??0)/(int)$compliance['total'])):0;if((int)($compliance['overdue']??0)>0)$blockers[]='One or more compliance requirements are overdue.';$o=$pdo->prepare('SELECT COUNT(*) AS total,SUM(kyc_status IN ("passed_external","not_applicable") AND accreditation_status IN ("verified_external","not_required") AND counsel_status IN ("approved","not_applicable")) AS complete FROM investor_onboarding_reviews WHERE round_id=?');$o->execute([$roundId]);$onboarding=$o->fetch(PDO::FETCH_ASSOC)?:[];$components['onboarding']=(int)($onboarding['total']??0)>0?(int)round(15*((int)($onboarding['complete']??0)/(int)$onboarding['total'])):0;if((int)($onboarding['complete']??0)<(int)($onboarding['total']??0))$blockers[]='Investor onboarding reviews are incomplete.';$p=$pdo->prepare('SELECT COUNT(*) AS total,SUM(status="complete") AS complete FROM investment_closing_packets WHERE round_id=?');$p->execute([$roundId]);$packets=$p->fetch(PDO::FETCH_ASSOC)?:[];$components['packets']=(int)($packets['total']??0)>0?(int)round(15*((int)($packets['complete']??0)/(int)$packets['total'])):0;if((int)($packets['complete']??0)<(int)($packets['total']??0))$blockers[]='Closing document packets are incomplete.';$v=$pdo->prepare('SELECT COUNT(*) FROM investment_financial_verification_requests WHERE round_id=? AND status="pending"');$v->execute([$roundId]);$pending=(int)$v->fetchColumn();$components['verification']=$pending===0?10:0;if($pending>0)$blockers[]='Financial verification requests are pending.';$target=max(1,(int)$round['target_raise_cents']);$q=$pdo->prepare('SELECT COALESCE(SUM(signed_amount_cents),0),COALESCE(SUM(verified_funded_cents),0) FROM investor_closing_records WHERE round_id=? AND status NOT IN ("withdrawn","declined")');$q->execute([$roundId]);[$signed,$funded]=$q->fetch(PDO::FETCH_NUM);$components['signed_progress']=min(10,(int)round(10*((int)$signed/$target)));$components['funded_progress']=min(10,(int)round(10*((int)$funded/$target)));$score=min(100,array_sum($components));$pdo->prepare('UPDATE investment_closing_profiles SET readiness_score=?,blockers_json=?,updated_by_user_id=?,updated_at=NOW() WHERE round_id=?')->execute([$score,$blockers?mg_investment_json_encode($blockers):null,(int)$actor['id'],$roundId]);mg_audit('investment_closing_readiness_refreshed','investment_round',['round_id'=>$round['public_id'],'score'=>$score,'components'=>$components,'blockers'=>$blockers],(int)$actor['id']);return ['readiness'=>['score'=>$score,'components'=>$components,'blockers'=>$blockers],'dashboard'=>mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']])];
}
